import { spawn } from 'node:child_process'; import { NativeExecutableInvocation } from './command-invocation.js';
const invocation = new NativeExecutableInvocation({ executable: process.execPath, args: ['worker.js'], cwd: null, env: null, stdio: 'ignore' });
spawn(invocation.executable, invocation.args, { ...invocation.processOptions(), shell: false });

